 if([IO.Path]::GetFileName($node.ExecutablePath) -eq 'codex.exe'){break}
 $node=Get-CimInstance Win32_Process -Filter "ProcessId=$($node.ParentProcessId)"
}
if([IO.Path]::GetFileName($node.ExecutablePath) -ne 'codex.exe'){throw 'Original Codex host not found'}
$hostId=$node.ProcessId
function Observe-Host {
 $p=Get-Process -Id $hostId
 $w=Get-CimInstance Win32_Process -Filter "ProcessId=$hostId"
 $path=$p.MainModule.FileName
 $f=Get-Item -LiteralPath $path
 $fileId= & 'C:/Windows/System32/fsutil.exe' file queryfileid $path
 if($LASTEXITCODE -ne 0){throw 'File identity query failed'}
 [ordered]@{observed_utc=[DateTime]::UtcNow.ToString('o');pid=$p.Id;parent_pid=$w.ParentProcessId;start_utc=$p.StartTime.ToUniversalTime().ToString('o');module_path=$path;file_id=($fileId -join ' ');length=$f.Length;write_utc=$f.LastWriteTimeUtc.ToString('o');sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower()}
}
$before=Observe-Host
$versionTime=[DateTime]::UtcNow.ToString('o')
$version= & $before.module_path --version
if($LASTEXITCODE -ne 0){throw 'Version query failed'}
$marker='codex-pair-boundary-'+[guid]::NewGuid().ToString()
